CREATE TABLE IF NOT EXISTS design_systems (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, version TEXT NOT NULL, typography JSONB NOT NULL DEFAULT '{}', color_palette JSONB NOT NULL DEFAULT '{}', spacing JSONB NOT NULL DEFAULT '{}', radius JSONB NOT NULL DEFAULT '{}', shadows JSONB NOT NULL DEFAULT '{}', breakpoints JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS design_systems_project_idx ON design_systems(project_id);
CREATE TABLE IF NOT EXISTS design_tokens (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL, value TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', semantic BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS design_components (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', dependencies JSONB NOT NULL DEFAULT '[]', used_by JSONB NOT NULL DEFAULT '[]', pages JSONB NOT NULL DEFAULT '[]', tests JSONB NOT NULL DEFAULT '[]', PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS design_component_tokens (component_id TEXT NOT NULL, design_system_id TEXT NOT NULL, token_id TEXT NOT NULL, PRIMARY KEY(component_id,design_system_id,token_id), FOREIGN KEY(component_id,design_system_id) REFERENCES design_components(id,design_system_id) ON DELETE CASCADE, FOREIGN KEY(design_system_id,token_id) REFERENCES design_tokens(design_system_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS design_component_variants (id BIGSERIAL PRIMARY KEY, component_id TEXT NOT NULL, design_system_id TEXT NOT NULL, name TEXT NOT NULL, props JSONB NOT NULL DEFAULT '{}', tokens JSONB NOT NULL DEFAULT '[]', FOREIGN KEY(component_id,design_system_id) REFERENCES design_components(id,design_system_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS design_patterns (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, components JSONB NOT NULL DEFAULT '[]', layout TEXT NOT NULL DEFAULT '', accessibility JSONB NOT NULL DEFAULT '[]', PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS design_layout_rules (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, rule TEXT NOT NULL, applies_to JSONB NOT NULL DEFAULT '[]', PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS design_motion_rules (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, duration_ms INTEGER NOT NULL DEFAULT 0, easing TEXT NOT NULL DEFAULT '', reduced_motion_behavior TEXT NOT NULL DEFAULT '', PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS design_accessibility_rules (id TEXT NOT NULL, design_system_id TEXT NOT NULL REFERENCES design_systems(id) ON DELETE CASCADE, name TEXT NOT NULL, requirement TEXT NOT NULL, severity TEXT NOT NULL, PRIMARY KEY(design_system_id,id));
CREATE TABLE IF NOT EXISTS knowledge_nodes (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, node_type TEXT NOT NULL, name TEXT NOT NULL, path TEXT NOT NULL DEFAULT '', attributes JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS knowledge_nodes_project_type_idx ON knowledge_nodes(project_id,node_type);
CREATE TABLE IF NOT EXISTS knowledge_edges (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, from_node TEXT NOT NULL REFERENCES knowledge_nodes(id) ON DELETE CASCADE, to_node TEXT NOT NULL REFERENCES knowledge_nodes(id) ON DELETE CASCADE, edge_type TEXT NOT NULL, attributes JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL, UNIQUE(project_id,from_node,to_node,edge_type));
CREATE INDEX IF NOT EXISTS knowledge_edges_from_idx ON knowledge_edges(project_id,from_node,edge_type);
CREATE INDEX IF NOT EXISTS knowledge_edges_to_idx ON knowledge_edges(project_id,to_node,edge_type);

CREATE TABLE IF NOT EXISTS agent_constitutions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, agent_id TEXT NOT NULL, identity TEXT NOT NULL, mission TEXT NOT NULL, authority JSONB NOT NULL DEFAULT '[]', restrictions JSONB NOT NULL DEFAULT '[]', decision_rules JSONB NOT NULL DEFAULT '[]', tool_rules JSONB NOT NULL DEFAULT '{}', verification_rules JSONB NOT NULL DEFAULT '[]', security_rules JSONB NOT NULL DEFAULT '[]', collaboration_rules JSONB NOT NULL DEFAULT '[]', policy JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(project_id,agent_id));
CREATE TABLE IF NOT EXISTS product_context_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, agent_id TEXT NOT NULL, task TEXT NOT NULL, context JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS impact_analyses (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, root_node TEXT NOT NULL, risk TEXT NOT NULL, files JSONB NOT NULL DEFAULT '[]', apis JSONB NOT NULL DEFAULT '[]', components JSONB NOT NULL DEFAULT '[]', tests JSONB NOT NULL DEFAULT '[]', affected_nodes JSONB NOT NULL DEFAULT '[]', approval_required BOOLEAN NOT NULL DEFAULT FALSE, reasons JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS autonomous_loop_plans (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, stages JSONB NOT NULL, delegates JSONB NOT NULL, status TEXT NOT NULL, blocked_stages JSONB NOT NULL DEFAULT '[]', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_activity (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, event_type TEXT NOT NULL, state TEXT NOT NULL, message TEXT NOT NULL, progress INTEGER, data JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS product_activity_project_time_idx ON product_activity(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS visual_qa_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, status TEXT NOT NULL, environment_status TEXT NOT NULL, viewport JSONB NOT NULL DEFAULT '{}', findings JSONB NOT NULL DEFAULT '[]', evidence JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
